PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry mean_reduce_dim1(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 batch,
    .param .u32 dim1,
    .param .u32 dim2
)
{
    // -------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------
    .reg .u64 %in_ptr, %out_ptr;
    .reg .u32 %batch, %dim1, %dim2;
    ld.param.u64 %in_ptr, [input_ptr];
    ld.param.u64 %out_ptr, [output_ptr];
    ld.param.u32 %batch,  [batch];
    ld.param.u32 %dim1,   [dim1];
    ld.param.u32 %dim2,   [dim2];

    // -------------------------------------------------
    // Thread / block indices
    // -------------------------------------------------
    .reg .u32 %tid, %bid_x, %bid_y;
    mov.u32 %tid,    %tid.x;
    mov.u32 %bid_x,  %ctaid.x;   // batch index
    mov.u32 %bid_y,  %ctaid.y;   // dim2 index

    // -------------------------------------------------
    // Partial sum in fp32
    // -------------------------------------------------
    .reg .f32 %sum;
    mov.f32 %sum, 0f0;

    .reg .u32 %i;
    mov.u32 %i, %tid;                // start element in dim1

LOOP_START:
    setp.ge.u32 %p1, %i, %dim1;
    @%p1 bra LOOP_END;

    // linear index = ((bid_x * dim1) + i) * dim2 + bid_y
    .reg .u64 %idx, %tmp;
    mul.lo.u64 %tmp, %bid_x, %dim1;      // bid_x * dim1
    add.u64 %tmp, %tmp, %i;              // + i
    mul.lo.u64 %tmp, %tmp, %dim2;        // * dim2
    add.u64 %tmp, %tmp, %bid_y;          // + bid_y
    mul.lo.u64 %idx, %tmp, 2;            // fp16 = 2 bytes
    add.u64 %idx, %in_ptr, %idx;         // address

    // load half, convert to float and accumulate
    .reg .u16 %h;
    ld.global.u16 %h, [%idx];
    .reg .f32 %f;
    cvt.f32.f16 %f, %h;
    add.f32 %sum, %sum, %f;

    // i += blockDim.x (256)
    add.u32 %i, %i, 256;
    bra LOOP_START;
LOOP_END:

    // -------------------------------------------------
    // Reduction in shared memory (256 threads)
    // -------------------------------------------------
    .shared .align 4 .b8 shmem[1024];        // 256 * 4 bytes

    // store partial sum
    .reg .u64 %sh_addr;
    mul.lo.u64 %sh_addr, %tid, 4;
    add.u64 %sh_addr, %sh_addr, shmem;
    st.shared.u32 [%sh_addr], %sum;

    bar.sync 0;

    // binary tree reduction
    .reg .u32 %offset;
    mov.u32 %offset, 128;
REDUCTION_LOOP:
    setp.eq.u32 %p2, %offset, 0;
    @%p2 bra REDUCTION_DONE;

    setp.lt.u32 %p3, %tid, %offset;
    @%p3 {
        .reg .u32 %addr1, %addr2;
        mul.lo.u32 %addr1, %tid, 4;
        add.u32 %addr2, %addr1, %offset*4;

        .reg .f32 %a, %b;
        ld.shared.u32 %a, [shmem + %addr1];
        ld.shared.u32 %b, [shmem + %addr2];
        add.f32 %a, %a, %b;
        st.shared.u32 [shmem + %addr1], %a;
    }
    bar.sync 0;
    shr.u32 %offset, %offset, 1;
    bra REDUCTION_LOOP;
REDUCTION_DONE:

    // -------------------------------------------------
    // Thread 0 writes the final mean
    // -------------------------------------------------
    setp.eq.u32 %p4, %tid, 0;
    @%p4 {
        .reg .f32 %total;
        ld.shared.u32 %total, [shmem];          // shared[0]

        // divide by dim1
        .reg .f32 %dim1_f;
        cvt.f32.u32 %dim1_f, %dim1;
        div.f32 %total, %total, %dim1_f;

        // convert back to half
        .reg .u16 %out_h;
        cvt.f16.f32 %out_h, %total;

        // output address = out_ptr + ((bid_x * dim2) + bid_y) * 2
        .reg .u64 %out_idx, %out_tmp;
        mul.lo.u64 %out_tmp, %bid_x, %dim2;
        add.u64 %out_tmp, %out_tmp, %bid_y;
        mul.lo.u64 %out_idx, %out_tmp, 2;
        add.u64 %out_idx, %out_ptr, %out_idx;
        st.global.u16 [%out_idx], %out_h;
    }

    ret;
}
